"""One local model, reused via ``programmer.ollama_provider``.

Not a benchmark: V0 picks one model for pipeline-validity smoke testing and
does not switch it mid-mission to rescue a failing task. The identifier is
configurable via ``GENERALISTA_MODEL``.
"""

from __future__ import annotations

import os

from . import _deps

DEFAULT_MODEL = os.environ.get("GENERALISTA_MODEL", "qwen3-coder:30b-a3b-q4_K_M")


class GeneralistaProvider:
    """Thin call surface: a prompt in, raw model text out. No parsing here."""

    def __init__(self, model: str = DEFAULT_MODEL) -> None:
        from programmer.ollama_provider import OllamaClient

        self.model = model
        self._client = OllamaClient(model=model)

    def available(self) -> bool:
        try:
            return self.model in self._client.available_models()
        except Exception:
            return False

    def generate(self, prompt: str, *, max_tokens: int = 2000) -> str:
        answer = self._client.generate(prompt, max_tokens=max_tokens)
        # _Answer carries .text in ollama_provider; be liberal about the shape.
        return getattr(answer, "text", None) or str(answer)

