from __future__ import annotations

import os
from dataclasses import dataclass
from pathlib import Path, PurePosixPath

GUARD_ID = "CONTAINMENT_GUARD_V1"

_WINDOWS_RESERVED_NAMES = frozenset(
    {"CON", "PRN", "AUX", "NUL"}
    | {f"COM{index}" for index in range(1, 10)}
    | {f"LPT{index}" for index in range(1, 10)}
)

_FORBIDDEN_NAME_CHARS = frozenset('<>:"|?*\\/') | frozenset(
    chr(code) for code in range(32)
)


class ContainmentError(RuntimeError):
    """Raised when a Programmer mission escapes its authorized root."""


@dataclass(frozen=True)
class TreeListing:
    """Everything the guard found under a root, as relative POSIX paths."""

    directories: tuple[PurePosixPath, ...]
    files: tuple[PurePosixPath, ...]

    @property
    def directory_names(self) -> tuple[str, ...]:
        return tuple(str(item) for item in self.directories)

    @property
    def file_names(self) -> tuple[str, ...]:
        return tuple(str(item) for item in self.files)


def is_reparse_point(path: Path) -> bool:
    """
    True when *path* is a symlink or a Windows junction / reparse point.

    The link is never followed.  A path that cannot be inspected is reported
    as a reparse point so that every caller fails closed.
    """
    try:
        if path.is_symlink():
            return True
    except OSError:
        return True

    try:
        return path.is_junction()
    except OSError:
        return True


def validate_relative_path(relative: str | PurePosixPath) -> PurePosixPath:
    """
    Normalize and validate a mission-relative path.

    Only forward slashes are accepted so that a manifest means exactly the
    same thing on every host.  Absolute paths, drive letters, ``..`` and
    Windows device names are rejected.
    """
    if isinstance(relative, PurePosixPath):
        text = str(relative)
    elif isinstance(relative, str):
        text = relative
    else:
        raise ContainmentError(
            f"Relative path must be a string, got {type(relative).__name__}"
        )

    if not text or not text.strip():
        raise ContainmentError("Relative path must not be empty")

    if "\\" in text:
        raise ContainmentError(
            f"Relative path must use forward slashes only: {text!r}"
        )

    if "\x00" in text:
        raise ContainmentError("Relative path must not contain NUL")

    if text.startswith("/"):
        raise ContainmentError(f"Relative path must not be absolute: {text!r}")

    if os.path.splitdrive(text)[0]:
        raise ContainmentError(
            f"Relative path must not carry a drive letter: {text!r}"
        )

    if text.endswith("/"):
        raise ContainmentError(
            f"Relative path must point at a file, not a directory: {text!r}"
        )

    parts = text.split("/")

    for part in parts:
        if part == "":
            raise ContainmentError(f"Relative path has an empty segment: {text!r}")
        if part == ".":
            raise ContainmentError(f"Relative path must not contain '.': {text!r}")
        if part == "..":
            raise ContainmentError(f"Relative path must not contain '..': {text!r}")
        if _FORBIDDEN_NAME_CHARS & set(part):
            raise ContainmentError(f"Relative path has an illegal segment: {part!r}")
        if part != part.strip() or part.endswith("."):
            raise ContainmentError(
                f"Relative path segment has illegal padding: {part!r}"
            )
        if part.split(".")[0].upper() in _WINDOWS_RESERVED_NAMES:
            raise ContainmentError(
                f"Relative path uses a reserved device name: {part!r}"
            )

    return PurePosixPath(text)


def _normcase(path: Path) -> str:
    return os.path.normcase(os.path.abspath(str(path)))


def _is_lexically_under(child: Path, parent: Path) -> bool:
    child_key = _normcase(child)
    parent_key = _normcase(parent)
    return child_key != parent_key and child_key.startswith(parent_key + os.sep)


