    """Everything the guard found under a root, as relative POSIX paths."""

    directories: tuple[PurePosixPath, ...]
    files: tuple[PurePosixPath, ...]

    @property
    def directory_names(self) -> tuple[str, ...]:
        return tuple(str(item) for item in self.directories)

    @property
    def file_names(self) -> tuple[str, ...]:
        return tuple(str(item) for item in self.files)


